(r, big) => {
    const n = big ? 100000 : r.int(1, 10);
    if (r.bool(0.5)) return [r.str(n, r.pick(["()*", "(*", "*)", "()**", "((*)"]))];
    // a balanced string with some brackets turned into stars, so true answers are common
    const len = n - (n % 2);
    let s = "", depth = 0;
    for (let i = 0; i < len; i++) {
      if (depth > 0 && (depth === len - i || r.bool())) { s += ")"; depth--; }
      else { s += "("; depth++; }
    }
    s = s.split("").map(c => (r.bool(0.3) ? "*" : c)).join("");
    if (r.bool(0.3)) s += r.pick(["(", ")", "*"]);
    return [s || "*"];
  }

