function canBalance(s: string): boolean {
  const n = s.length;
  let can = new Array(n + 2).fill(false);
  can[0] = true;
  for (const ch of s) {
    const next = new Array(n + 2).fill(false);
    for (let b = 0; b <= n; b++) {
      if (!can[b]) continue;
      if (ch !== ")") next[b + 1] = true;
      if (ch === "*") next[b] = true;
      if (ch !== "(" && b > 0) next[b - 1] = true;
    }
    can = next;
  }
  return can[0];
}

