function canBalance(s: string): boolean {
  const opens: number[] = [], stars: number[] = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "(") opens.push(i);
    else if (s[i] === "*") stars.push(i);
    else if (opens.length) opens.pop();
    else if (stars.length) stars.pop();
    else return false;
  }
  while (opens.length) {
    if (!stars.length || stars[stars.length - 1] < opens[opens.length - 1]) return false;
    opens.pop();
    stars.pop();
  }
  return true;
}

